function Onboarding({ engine, t, close }: { engine: Engine; t: Translate; close: () => void }) {
  const initialRoute = engine.routes.find(route => route.enabled);
  const [step, setStep] = useState(0); const [software, setSoftware] = useState('OBS Studio'); const [platform, setPlatform] = useState(initialRoute?.platform ?? 'twitch'); const [server, setServer] = useState(initialRoute?.upstream_url ?? platforms[0].server); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [serverInvalid, setServerInvalid] = useState(false);
  const selectedRoute = engine.routes.find(route => route.platform === platform);
  const stepHeading = useRef<HTMLHeadingElement>(null);
  const previousStep = useRef(step);
  useEffect(() => { if (previousStep.current !== step) { stepHeading.current?.focus(); previousStep.current = step; } }, [step]);
  const port = engine.status?.endpoints?.rtmp_port ?? 0; const apiPort = engine.status?.endpoints ? Number(new URL(engine.status.endpoints.api_base).port) : 0;
  const titles = [t('Votre logiciel de stream', 'Your streaming software'), t('Votre destination', 'Your destination'), t('Relier votre sortie', 'Connect your output'), t('Informer votre public', 'Keep your audience informed'), t('Vérifier votre signal', 'Check your signal')];
  const next = async () => { setBusy(true); setError(''); try { if (step === 1) { setServerInvalid(false); if (!isServerUrl(server)) { setServerInvalid(true); setError(t('Indiquez une adresse de serveur commençant par rtmp:// ou rtmps://, sans identifiants ni clé de stream.', 'Enter a server address starting with rtmp:// or rtmps://, without credentials or a stream key.')); return; } const item = platforms.find(value => value.id === platform)!; const existing = engine.routes.find(route => route.platform === platform); if (!existing || !existing.enabled || existing.upstream_url !== server) await api.saveRoute({ ...(existing ?? { id: platform, name: item.name, platform, local_app: platform, include_in_group: true }), enabled: true, upstream_url: server }); await engine.refresh(); } if (step === 4) { await api.savePreferences({ ...(engine.preferences ?? defaultPreferences), onboarding_complete: true }); await engine.refresh(); close(); } else setStep(value => value + 1); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setBusy(false); } };
  return <Dialog title="Open-Delay" close={close} footer={<div className="dialog-actions">{step === 3 && <button className="text-button" disabled={busy} onClick={() => setStep(4)}>{t('Passer cette étape', 'Skip this step')}</button>}<button className="button quiet" disabled={step === 0 || busy} onClick={() => setStep(value => value - 1)}>{t('Précédent', 'Back')}</button><button className="button primary" disabled={busy} onClick={() => void next()}>{busy ? t('En cours…', 'Working…') : step === 4 ? t('Ouvrir ma régie', 'Open my dashboard') : t('Continuer', 'Continue')}<Icon name="arrow" size={16}/></button></div>}><div className="onboarding"><SetupProgress steps={[t('Logiciel', 'Software'), t('Destination', 'Output'), t('Connexion', 'Connection'), t('Overlay · optionnel', 'Overlay · optional'), t('Vérification', 'Check')]} current={step} onBack={setStep} label={t('Étapes de configuration', 'Setup steps')} disabled={busy}/><p className="eyebrow">{t('ÉTAPE', 'STEP')} {String(step + 1).padStart(2, '0')} / 05</p><h2 ref={stepHeading} tabIndex={-1}>{titles[step]}</h2>{step === 0 && <><p>{t('On garde vos habitudes. Choisissez le logiciel que vous utilisez.', 'Keep your workflow. Choose the software you use.')}</p><div className="choice-grid">{['OBS Studio', 'Streamlabs'].map(value => <button key={value} className={software === value ? 'selected' : ''} aria-pressed={software === value} onClick={() => setSoftware(value)}><ServiceLogo service={value === 'OBS Studio' ? 'obs' : 'streamlabs'} size={28}/><strong>{value}</strong>{software === value && <Icon name="check" size={16}/>}</button>)}</div></>}{step === 1 && <><p>{t('Votre clé reste dans votre logiciel. Open-Delay a seulement besoin du serveur.', 'Your key stays in your software. Open-Delay only needs the server.')}</p><label>{t('Plateforme', 'Platform')}<SelectField label={t('Plateforme', 'Platform')} value={platform} onChange={value => { setServerInvalid(false); setError(''); setPlatform(value); setServer(engine.routes.find(route => route.platform === value)?.upstream_url ?? platforms.find(item => item.id === value)?.server ?? ''); }} options={platforms.map(item => ({ value: item.id, label: item.name }))}/></label><label>{t('Serveur', 'Server')}<input value={server} placeholder="rtmps://server.example/app" aria-invalid={serverInvalid || undefined} aria-describedby={serverInvalid ? "onboarding-server-error" : undefined} onChange={event => { setServer(event.target.value); if (serverInvalid) { setServerInvalid(false); setError(''); } }}/></label></>}{step === 2 && <><p>{t(`Dans ${software}, ouvrez les paramètres de stream. Choisissez un serveur personnalisé et remplacez seulement son adresse.`, `In ${software}, open stream settings. Select a custom server and replace only its address.`)}</p><Copy value={`rtmp://127.0.0.1:${port}/${selectedRoute?.local_app ?? platform}`} t={t}/><div className="info-note"><Icon name="check"/><p>{t('Conservez la clé de votre plateforme, exactement comme avant.', 'Keep your platform key exactly as before.')}</p></div></>}{step === 3 && <><p>{t('Ajoutez une source Navigateur en 1920 × 1080 dans votre scène. Vous pourrez personnaliser son style dans la page Overlay.', 'Add a 1920 × 1080 Browser source to your scene. Customize its style on the Overlay page.')}</p><Copy value={`http://127.0.0.1:${apiPort}/overlay?managed=true`} t={t}/><p className="muted">{t('Cette étape est facultative en mode Instant.', 'This step is optional in Instant mode.')}</p></>}{step === 4 && <><div className="complete-mark"><Icon name="check" size={32}/></div><p role="status" className="onboarding-signal">{engine.status?.routes.some(route => route.id === (selectedRoute?.id ?? platform) && route.is_connected) ? t('Signal reçu. Vous pouvez préparer votre premier délai dans la régie.', 'Signal received. You can prepare your first delay in the dashboard.') : t('En attente de votre signal. Démarrez la sortie dans OBS ou Streamlabs, puis vérifiez son état dans la régie.', 'Waiting for your signal. Start the output in OBS or Streamlabs, then check its state in the dashboard.')}</p><p className="muted">{t('Gratuit. Local. Sans compte.', 'Free. Local. No account.')}</p></>}{error && <p id="onboarding-server-error" role="alert" className="field-error">{error}</p>}</div></Dialog>;
}
